// Adaptive trapezoidal integration with error control
double fa = f(a);
double fb = f(b);
double c = (a + b) / 2.0;
double fc = f(c);
double T = (fb + fa) * (b - a) / 2.0;
double T2 = T + (fc - (fa + fb) / 2.0) * (b - a) / 2.0;
double error = std::abs(T2 - T) / 3.0;

if (error <= 15.0 * precision) {
    return T2 + (T2 - T) / 15.0;
}

double d = (a + c) / 2.0;
double e = (c + b) / 2.0;
double fd = f(d);
double fe = f(e);
double T1 = (fa + fc) * (c - a) / 2.0;
double T3 = T1 + (fd - (fa + fc) / 2.0) * (c - a) / 2.0;
double T4 = (fc + fb) * (b - c) / 2.0;
double T5 = T4 + (fe - (fc + fb) / 2.0) * (b - c) / 2.0;

double result = T3 + T5;
double error1 = std::abs(T3 - T1) / 3.0;
double error2 = std::abs(T5 - T4) / 3.0;

if (error1 <= 15.0 * precision) {
    result += (T3 - T1) / 15.0;
}
if (error2 <= 15.0 * precision) {
    result += (T5 - T4) / 15.0;
}

return adaptive_trapezoidal(f, a, c, precision / std::sqrt(2.0)) +
       adaptive_trapezoidal(f, c, b, precision / std::sqrt(2.0));

